import{_ as t,c as a,o,ag as i}from"./chunks/framework.Ci10AEOF.js";const m=JSON.parse('{"title":"Migrating from Mirth Connect","description":"What changes, what does not, and what to prepare before moving a Mirth Connect server onto OIE","frontmatter":{"title":"Migrating from Mirth Connect","description":"What changes, what does not, and what to prepare before moving a Mirth Connect server onto OIE"},"headers":[],"relativePath":"engine/migrating_from_mirth_connect.md","filePath":"engine/migrating_from_mirth_connect.md","lastUpdated":1793057853000}'),n={name:"engine/migrating_from_mirth_connect.md"};function r(s,e,h,d,l,c){return o(),a("div",null,e[0]||(e[0]=[i('<h1 id="migrating-from-mirth-connect" tabindex="-1">Migrating from Mirth Connect <a class="header-anchor" href="#migrating-from-mirth-connect" aria-label="Permalink to &quot;Migrating from Mirth Connect&quot;">​</a></h1><p>A migration moves an existing Mirth Connect server onto OIE on the same host, in this order:</p><ul><li>Install OIE alongside it, without starting it</li><li>Start OIE once on its own to prove it runs, before anything of Mirth&#39;s is touched</li><li>Transplant the relevant configurations</li><li>Stop Mirth and start OIE</li><li>Disable the Mirth installation</li></ul><p>Then follow the procedure for your platform: <strong><a href="./migrating_linux.html">Linux</a></strong>, <strong><a href="./migrating_windows.html">Windows</a></strong> or <strong><a href="./migrating_macos.html">macOS</a></strong>.</p><div class="warning custom-block"><p class="custom-block-title">NextGen premium extensions do not migrate</p><p>Work out what replaces anything you depend on before you start. See <a href="#extension-compatibility">Extension compatibility</a>.</p></div><p>OIE kept Mirth&#39;s filenames, so an OIE installation has its own <code>conf/mirth.properties</code> and <code>logs/mirth.log</code>. Most files sit at the same relative path in both installations, so the full path is what tells them apart. Each platform page states the paths it uses.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><ul><li><strong>The same host.</strong> Mirth and OIE are installed side by side and the cutover happens in one maintenance window.</li><li><strong>Either database.</strong> An external PostgreSQL, MySQL, Oracle or SQL Server, or the embedded Derby database. Steps 6 and 8 branch on which one you run.</li><li><strong>The native installer with a bundled JRE.</strong> The server runs on the bundled runtime, so the host&#39;s Java version does not matter.</li><li>Docker is not covered here. <a href="./upgrade_guide.html">Upgrade Guide</a> has a container path for OIE-to-OIE upgrades.</li></ul><p>The procedure has been used to migrate from Mirth Connect 4.5.x. <a href="#what-migrates">What migrates</a> describes what the server does with an older starting version.</p><h2 id="what-migrates" tabindex="-1">What migrates <a class="header-anchor" href="#what-migrates" aria-label="Permalink to &quot;What migrates&quot;">​</a></h2><p>The server records a schema version in the database. On startup it migrates from that version up to its own.</p><p>From Mirth Connect 4.3.0 or later, OIE 4.7.0 changes no table and no column. The recorded version becomes 4.7.0, which Mirth Connect cannot run on, so your database backup is the only way back. See <a href="./upgrade_guide.html#version-specific-notes">Version-specific notes</a>.</p><p>From a version below 4.3.0, the schema changes as well.</p><div class="warning custom-block"><p class="custom-block-title">Merge mirth.properties rather than replacing it</p><p>The database migrates from the version recorded in the database, not from <code>mirth.properties</code>. The <code>version</code> property in <code>mirth.properties</code> records which version the file came from: at startup the server applies every later version&#39;s property changes to the file, then sets <code>version</code> to its own. Copying Mirth&#39;s file wholesale replaces OIE&#39;s shipped settings, such as its password policy, with Mirth&#39;s.</p></div><h2 id="extension-compatibility" tabindex="-1">Extension compatibility <a class="header-anchor" href="#extension-compatibility" aria-label="Permalink to &quot;Extension compatibility&quot;">​</a></h2><p>An extension declares a <code>&lt;mirthVersion&gt;</code> in its <code>plugin.xml</code>, <code>source.xml</code> or <code>destination.xml</code>. The server compares that value against its own version as an exact string. There is no version range.</p><p>An extension built for Mirth Connect 4.5.2 declares <code>4.5.2</code> and will not load on OIE 4.7.0. The server logs an error and does not load it.</p><p>The version string decides whether the server loads an extension. Whether it then works is up to the extension&#39;s own code. For an extension you build or maintain yourself, the value takes a comma-separated list, so <code>4.5.2,4.7.0</code> declares both. For anything you did not build, get a build published for 4.7.0 rather than editing someone else&#39;s metadata.</p><h3 id="premium-extensions" tabindex="-1">Premium extensions <a class="header-anchor" href="#premium-extensions" aria-label="Permalink to &quot;Premium extensions&quot;">​</a></h3><p>Nothing in OIE validates a license: extension metadata carries no license field, and installing an extension checks your permission and the version string, nothing else. A paid extension can carry its own license check inside its own code, and whether a license issued for Mirth Connect functions from an OIE installation is a question for whoever sold it to you.</p><p>Examples of premium capabilities that have a community plugin:</p><table tabindex="0"><thead><tr><th>Capability</th><th>Community plugin</th><th>What to expect</th></tr></thead><tbody><tr><td>TLS and certificate management</td><td><a href="https://github.com/NovaMap-Health/tls-manager-plugin" target="_blank" rel="noreferrer">TLS Manager</a>, NovaMap-Health</td><td>Channels configured against the premium plugin&#39;s TLS need reworking. Channels on non-TLS connectors are unaffected</td></tr><tr><td>Channel and code template history</td><td><a href="https://github.com/diridium-com/simple-channel-history" target="_blank" rel="noreferrer">Channel &amp; Code Template History</a>, diridium-com</td><td>History starts from the day you install it. Existing history does not come across</td></tr></tbody></table><p>Neither plugin is published as a replacement for a paid product. The <a href="https://openintegrationengine.org/plugins/" target="_blank" rel="noreferrer">plugin directory</a> is the current list.</p><p><em>Mirth Connect and NextGen are trademarks of NextGen Healthcare, which is not affiliated with, does not endorse, and does not sponsor this project.</em></p><h2 id="what-the-keystore-holds" tabindex="-1">What the keystore holds <a class="header-anchor" href="#what-the-keystore-holds" aria-label="Permalink to &quot;What the keystore holds&quot;">​</a></h2><p><code>appdata/keystore.jks</code> holds two things under fixed aliases. <code>mirthconnect</code> is the TLS certificate the server presents. <code>encryption</code> is an AES secret key, and what that key covers decides whether the keystore has to come across with the database.</p><p>The key is used for:</p><ul><li>Message content, attachments and custom metadata columns written to the database. Each has its own per-channel setting, and all three are off by default. With only message content on, attachments and custom metadata columns are stored in plain text. An attachment a script adds with <code>addAttachment()</code> is stored in plain text even with all three on.</li><li>The <code>database.password</code> and <code>database-readonly.password</code> values in <code>mirth.properties</code>, when <code>encryption.properties</code> is enabled. That defaults to off. An encrypted value is visible in the file by its <code>{enc}</code> prefix.</li><li>Anything a channel script encrypts through the <code>EncryptionUtil</code> API.</li><li>Messages written by a message export or an archive with the Encrypt option on.</li><li>Files the Administrator exports, such as channels, when <code>encryption.export = 1</code> is set in <code>mirth.properties</code>. That defaults to off.</li></ul><p>If none of those apply, the keystore carries your TLS identity and nothing else. If any of them apply, pointing OIE at Mirth&#39;s database without Mirth&#39;s keystore leaves that data unreadable.</p><div class="warning custom-block"><p class="custom-block-title">The keystore and its passwords travel together</p><p><code>keystore.storepass</code> and <code>keystore.keypass</code> must be the values that match the copied <code>keystore.jks</code>. On a mismatch the server logs <code>Could not initialize security settings.</code> and <strong>carries on starting</strong>. Check <code>logs/mirth.log</code> for that line.</p></div><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Take the backups listed in <a href="./upgrade_guide.html#_1-back-up-everything">Upgrade Guide</a>. They apply here unchanged, and the database backup is the rollback.</p><p>Two additions specific to this move:</p><ul><li><strong>Record what the Mirth service runs as</strong> and what owns its install directory. Step 4 reproduces both.</li><li><strong>List your extensions and their declared versions.</strong> Step 6 checks them against 4.7.0.</li></ul><div class="warning custom-block"><p class="custom-block-title">A server configuration export is not a backup</p><p>The export at <strong>Settings &gt; Server Tasks &gt; Backup Config</strong>, and <code>exportcfg</code> on the CLI, omits user accounts entirely, and the matching restore has no step that would put them back. It also excludes the keystore, <code>mirth.properties</code> and the message database. It will not rebuild a server.</p></div><h2 id="platforms" tabindex="-1">Platforms <a class="header-anchor" href="#platforms" aria-label="Permalink to &quot;Platforms&quot;">​</a></h2><p>The eleven steps are the same on every platform. What differs is how you set the service account, change file ownership, and start, stop and disable a service.</p><ul><li><strong><a href="./migrating_linux.html">Linux</a></strong>, complete</li><li><strong><a href="./migrating_windows.html">Windows</a></strong>, not written yet</li><li><strong><a href="./migrating_macos.html">macOS</a></strong>, not written yet</li></ul><p>If you have done this migration on Windows or macOS, those pages would be welcome. The Linux page is the template: the same eleven steps, with the service and file commands replaced. See <a href="./contributing.html">Contributing</a>.</p>',39)]))}const g=t(n,[["render",r]]);export{m as __pageData,g as default};
